function HSETS(){
 const ix=new Map(CARDS.map((c,i)=>[c.c,i])),used=new Set(),o=[],G=GR();
 const add=(g,h,added=false)=>{
  const supplemental=h.k!=='Unit',t=supplemental?'Extra set '+h.n:'Unit '+h.n;
  const f=(GN[g]||'Other')+' · '+t;
  o.push({g,t,f,s:added?f:t,c:[...h.c],a:added,supplemental,id:g+':'+t});
  h.c.forEach(c=>used.add(c));
 };
 // Official unit contents and order are never shortened by active selection.
 CHK().forEach(h=>add(G,h));
 const extras=new Set(CARDS.filter(c=>!used.has(c.c)).map(c=>c.c));
 for(const g of ['K','1','2','3','4','5'].filter(g=>g!==G)){
  for(const [n,chars] of QU(g)){
   if([...chars].some(c=>extras.has(c))){
    add(g,{k:'Unit',n,c:[...chars]},true);
    [...chars].forEach(c=>extras.delete(c));
   }
  }
 }
 // Remaining supplemental characters have no PDF unit; label them explicitly.
 const extraGroups={};
 for(const c of CARDS.filter(c=>extras.has(c.c))){const g=(c.g||'?')[0];(extraGroups[g]||=[]).push(c.c)}
 for(const [g,chars] of Object.entries(extraGroups)){
  for(let i=0;i<chars.length;i+=10)add(g,{k:'Extra',n:i/10+1,c:chars.slice(i,i+10)},true);
 }
 const m=x=>(S.pts[x]||0)>=MASTER;
 const cur=o.findIndex(h=>h.g===G&&!h.a&&h.c.some(x=>ix.has(x))&&!h.c.every(m));
 HS=o;return {o,cur,ix}
}let HS=[];
