 $('gcopy').onclick=()=>{const c=backup(),g=$('gcopy'),l=$('gcl'),h=l.innerHTML,ok=()=>{localStorage.setItem('zh_bk',Date.now());$('glast').textContent='Last copied: '+BKA();$('gcf').innerHTML='';l.innerHTML='✅ Copied! Paste it somewhere safe.';g.style.background='var(--success-soft)';g.style.color='var(--success)';clearTimeout(g._t);g._t=setTimeout(()=>{l.innerHTML=h;g.style.background='';g.style.color=''},3000)};try{if(!navigator.clipboard?.writeText)throw Error();Promise.resolve(navigator.clipboard.writeText(c)).then(ok,()=>backupCopyFallback(c))}catch{backupCopyFallback(c)}};
